"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["823"],{61258(e,t,n){n.d(t,{Ay:()=>r,RM:()=>o});var a=n(74848),s=n(28453),i=n(66422);let o=[{value:"Comments",id:"comments",level:3}];function l(e){let t={blockquote:"blockquote",h1:"h1",h3:"h3",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"the-host--out-in-the-world-all-debts-must-be-repaid",children:"The Host \u2014 Out in the World, All Debts Must Be Repaid!"})}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsx)(t.p,{children:"2006/7/1 12:23:15"}),"\n"]}),"\n",(0,a.jsxs)("div",{style:{textAlign:"center"},children:[(0,a.jsx)("img",{src:(0,i.Ay)("/img/entertainment/thehost/1.jpeg")}),(0,a.jsx)("br",{}),(0,a.jsx)("br",{})]}),"\n",(0,a.jsx)(t.p,{children:"When politics defeats art; when the host remains magically host-like; when that melancholy blue is fatedly swallowed by that cold white; when the most formidable crow, the most formidable beak \u2014 that weapon more effective than the Tyrant's Spear, the Jade Sword, the Longevity Blade, the Passion Ring, the Parting Hook, the Fist, and the Peacock Plume \u2014 unprecedentedly fails; this night was thus historically disgraced."}),"\n",(0,a.jsx)(t.p,{children:"When politics is needed, even that tiny East Asian football nation can make the semi-finals. How then could this Germany, with its countless honors and traditions, stop at the quarterfinals? When the legend of the host tediously continues the same boring story in different national versions, why bother examining the specific plot points? When the world demands a game between Hitler and Mussolini, why question whether the game is political? When the melancholy of blue has been fated, the cruelty of white is merely for the final blood. When even the most crow-like crow can become a magpie, the world will thus fall ugly into the night."}),"\n",(0,a.jsx)(t.p,{children:"The ultimate PK between two teams that have never lost a World Cup penalty shootout was merely one page of this ugly script's self-defeating cover-up. When that German man imitated that Pole, clowning around on the goal line, Liverpool's glorious victory was thereby disgraced. Maradona's shamelessness with the Hand of God in 1986 was already repaid by Germany's even greater shamelessness with the Divine Dive in 1990. And the Germans' subsequent 16 years of repayment were apparently not profound enough \u2014 so let new shamelessness continue to prepare bullets for new repayment. Four years hence in South Africa, when Germany is no longer the political excuse, repayment will pierce the ugliness of the night with the force of a bullet."}),"\n",(0,a.jsx)(t.p,{children:"Go ask France, England, and others \u2014 the host's shamelessness has aftereffects! The host \u2014 out in the world, all debts must be repaid! Setting aside France's laughable 2002 repayment, and the even more obvious fact that a certain East Asian football nation's ongoing repayment will certainly not be completed in a mere 4 years \u2014 just look at the Germans. No need to grumble about 1966's goal-line controversy anymore; England has already paid a 40-year price for that goal line \u2014 longer than their impotence against Sweden. But 40 years is not the end of this repayment. The magical crow has announced \"England and Brazil will meet in the semifinals.\" Without the most shameless politics, the crow will still be magical. And Germany \u2014 do you wish to become the German Patient, surpassing 40 years like the English Patient?"}),"\n",(0,a.jsx)(t.h3,{id:"comments",children:"Comments"}),"\n",(0,a.jsx)("div",{class:"blog-comment",children:(0,a.jsxs)(t.p,{children:[(0,a.jsx)("span",{class:"blog-comment-chan",children:"\u7F20\u4E2D\u8BF4\u7985"})," 2006/7/2 2:43:48",(0,a.jsx)("br",{}),'\nBut 40 years is not the end of this repayment. The magical crow has announced "England and Brazil will meet in the semifinals." Without the most shameless politics, the crow will still be magical.']})})]})}function r(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},89727(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>m,frontMatter:()=>l,contentTitle:()=>r,toc:()=>c,assets:()=>h});var a=JSON.parse('{"id":"entertainment/thehost","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/entertainment/thehost.md","sourceDirName":"entertainment","slug":"/entertainment/thehost","permalink":"/en/entertainment/thehost","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"thehost","title":"","hide_table_of_contents":true,"sidebar_label":"Host Nation: In the Game, All Debts Must Be Repaid! (2006/7/1 12:23:15)"},"sidebar":"entertainmentSidebar","previous":{"title":"Zhang Liangying\'s Soul Possession, Huang Jianxiang Belts Out Dolphin Notes (2006/6/27 12:34:16)","permalink":"/en/entertainment/huangjx"},"next":{"title":"England: The Same Old Macbeth Story! (2006/7/2 2:39:34)","permalink":"/en/entertainment/macbeth"}}'),s=n(74848),i=n(28453),o=n(61258);let l={id:"thehost",title:"",hide_table_of_contents:!0,sidebar_label:"Host Nation: In the Game, All Debts Must Be Repaid! (2006/7/1 12:23:15)"},r,h={},c=[...o.RM];function d(e){return(0,s.jsx)(o.Ay,{})}function m(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>l});var a=n(96540);let s={},i=a.createContext(s);function o(e){let t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function l(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);